import com.google.common.base.Joiner;
import static org.junit.Assert.assertEquals;

public class PatternMatchingTest {

    public static String patternMatches(String message) {
        return Joiner.on(",").join(message.split(","));
    }

    public static void main(String[] args) {
        assertEquals(patternMatches("^[A-Z]+[0-9]+$"), "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789");
        assertEquals(patternMatches("^[A-Z]+$"), "ABCDEFGHIJKLMNOPQRSTUVWXYZ");
        assertEquals(patternMatches("^[A-Z]+[0-9]{4}$"), "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456");
        assertEquals(patternMatches("^[A-Z]+$", "[0-9]+$"), "ABCDEFGHIJKLMNOPQRSTUVWXYZ");
    }
}
